#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_appendf_resize_failure(void) {
    // Setup: create a buffer with some initial data
    buffer_t *buf = helper_make_buffer_with_data("abc");
    TEST_ASSERT_NOT_NULL(buf);

    // To trigger the path, we need buffer_resize to fail.
    // We simulate this by temporarily replacing buffer_resize with a stub that returns -1.
    // Since we cannot redefine buffer_resize here, we assume a test double is linked in test build.
    // The test double should be set up to return -1 for this test.

    // Test: attempt to append formatted string, expecting failure due to resize
    int ret = buffer_appendf(buf, " %d %s", 42, "test");

    // Assertions: function should return -1, buffer should be unchanged
    TEST_ASSERT_EQUAL_INT(-1, ret);
    helper_assert_buffer_data_equals(buf, "abc");
    helper_assert_buffer_length(buf, 3);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_appendf_resize_failure);
    return UNITY_END();
}

